import{_ as i,b as e,c as t,g as o}from"./chunks/framework.86O3EbG5.js";const x=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach-homework/21.md","filePath":"articles/ai/books/ai-modern-approach-homework/21.md"}'),d={name:"articles/ai/books/ai-modern-approach-homework/21.md"};function n(r,a,p,s,h,_){return e(),t("div",null,[...a[0]||(a[0]=[o('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 21 章&lt;深度学习&gt;，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来</p><h2 id="一个简单的单层神经网络-逻辑回归-有2个输入-x-1-x-2-权重-w-1-0-5-w-2-0-5-偏置-b-0-2-激活函数为sigmoid。给定输入-x-1-1-x-2-0-计算" tabindex="-1">一个简单的单层神经网络（逻辑回归）有2个输入 x_1,x_2，权重 w_1=0.5,w_2=-0.5，偏置 b=0.2，激活函数为Sigmoid。给定输入 x_1=1,x_2=0，计算：</h2><p>(1) 净输入 z。 (2) 输出 a=σ(z)。 (3) 若真实标签 y=1，二元交叉熵损失 L=-ylog⁡a-(1-y)log⁡(1-a) 的值。</p><h2 id="简述反向传播算法的核心步骤。对于一个三层网络-输入层→隐藏层→输出层-写出输出层权重梯度的计算表达式-使用链式法则-。" tabindex="-1">简述反向传播算法的核心步骤。对于一个三层网络（输入层→隐藏层→输出层），写出输出层权重梯度的计算表达式（使用链式法则）。</h2><h2 id="解释梯度消失和梯度爆炸现象及其对深度网络训练的影响。列举三种缓解方法。" tabindex="-1">解释梯度消失和梯度爆炸现象及其对深度网络训练的影响。列举三种缓解方法。</h2><h2 id="手动计算反向传播-考虑一个简单的两层网络-无隐藏层-即逻辑回归-但为了练习手动计算-假设单层-。输入-x-2-真实-y-1。权重-w-0-5-偏置-b-0-激活函数-sigmoid-损失函数为均方误差-l-1-2-a-y-2。" tabindex="-1">手动计算反向传播：考虑一个简单的两层网络（无隐藏层，即逻辑回归，但为了练习手动计算，假设单层）。输入 x=2，真实 y=1。权重 w=0.5，偏置 b=0，激活函数 Sigmoid，损失函数为均方误差 L=1/2(a-y)^2。</h2><p>(1) 前向传播计算 a 和 L。 (2) 反向传播计算梯度 ∂L/∂w 和 ∂L/∂b。 (3) 使用学习率 η=0.1 更新 w 和 b。</p><h2 id="卷积神经网络参数计数-一个卷积层-输入特征图尺寸-32×32×3-使用32个-3×3-卷积核-步长1-无填充-求该层的参数量-包括偏置-。如果使用-2×2-最大池化-步长2-输出特征图的尺寸是多少-写出计算过程。" tabindex="-1">卷积神经网络参数计数：一个卷积层，输入特征图尺寸 32×32×3，使用32个 3×3 卷积核（步长1，无填充），求该层的参数量（包括偏置）。如果使用 2×2 最大池化（步长2），输出特征图的尺寸是多少？写出计算过程。</h2><h2 id="lstm门控机制-lstm单元的三个门-输入门、遗忘门、输出门-分别起什么作用-写出遗忘门的计算公式-符号含义-。为什么lstm能缓解长期依赖问题" tabindex="-1">LSTM门控机制：LSTM单元的三个门（输入门、遗忘门、输出门）分别起什么作用？写出遗忘门的计算公式（符号含义）。为什么LSTM能缓解长期依赖问题？</h2><h2 id="图像分类深度学习流程设计-你有一个包含10万个图像的数据集-分为10个类别。你需要设计一个cnn模型进行图像分类。" tabindex="-1">图像分类深度学习流程设计：你有一个包含10万个图像的数据集，分为10个类别。你需要设计一个CNN模型进行图像分类。</h2><p>(1) 描述数据预处理步骤（归一化、数据增强等）。 (2) 画出你设计的CNN结构（至少包含卷积层、池化层、全连接层），并说明每层参数（卷积核大小、数量）。 (3) 选择损失函数、优化器，并解释理由。 (4) 如何判断模型是否过拟合？如果过拟合，你会采取哪些措施？</p><h2 id="rnn与序列预测-假设你想用rnn预测股票价格-时间序列-。" tabindex="-1">RNN与序列预测：假设你想用RNN预测股票价格（时间序列）。</h2><p>(1) 解释为什么RNN适合这类问题，相比前馈网络有何优势。 (2) 如果使用简单的RNN，可能会遇到什么训练问题？如何改进（使用LSTM或GRU）？ (3) 对于超长序列（如数千时间步），即使LSTM也可能失效，你会采用什么技术（例如注意力机制、截断BPTT）？ (4) 评价模型性能的常用指标有哪些？</p><h2 id="生成对抗网络-gan-原理" tabindex="-1">生成对抗网络（GAN）原理：</h2><p>(1) 解释生成器（Generator）和判别器（Discriminator）的博弈过程。 (2) 写出GAN的训练目标函数（极小极大博弈）。 (3) GAN训练中常见的困难（如模式崩溃、不收敛），如何缓解？ (4) 相比于VAE，GAN生成的样本通常更清晰，为什么？</p><h2 id="实际应用-情感分析" tabindex="-1">实际应用：情感分析：</h2><p>你需要为电影评论构建一个情感分类器（正面/负面）。数据为文本句子。 (1) 设计特征表示方法（如词嵌入+RNN、或使用预训练模型如BERT）。 (2) 画出网络结构（嵌入层、RNN/LSTM、全连接、输出）。 (3) 如何处理变长输入序列？ (4) 如果只有少量标注数据（1000条），但有大量无标注评论，你会使用什么技术（如半监督学习、预训练+微调）？</p>',17)])])}const N=i(d,[["render",n]]);export{x as __pageData,N as default};
